package dev.theoria.gear;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.jspecify.annotations.Nullable;

/**
 * The gear table, read from the jar ({@code theoria/gear.json}, generated by generator/gear.py from data/balance/*.csv + data/materials.csv).
 * It is a jar resource and not a datapack on purpose: items and blocks are registered, and vanilla item components are bound,
 * before any datapack exists — same reason as {@code technical_caps.json} (ADR-003 Karar 2). Adding a material = a CSV row.
 */
public final class GearData {
    public static final String RESOURCE = "/theoria/gear.json";
    public static final List<String> ARMOR_PIECES = List.of("helmet", "chestplate", "leggings", "boots");
    public static final List<String> TOOL_KINDS = List.of("sword", "axe", "pickaxe", "shovel", "hoe", "spear");

    /** Per-piece armor: points and durability by piece; toughness is the whole set's (the piece carries a quarter). */
    public record Armor(Map<String, Integer> points, double toughness, Map<String, Integer> durability, double speed, double knockback) {}

    /** Damage is the displayed total (player base 1 included); speed is attacks per second. */
    public record Kind(double damage, double speed) {}

    public record Tools(int idx, int durability, double miningSpeed, Map<String, Kind> kinds, double[] spear) {}

    public record Material(String id, boolean vanilla, int idx, String prefix, int enchantability, String equipSound, String ingredient,
            @Nullable Armor armor, @Nullable Tools tools) {
        /** Registered item id of a piece: vanilla keeps minecraft:golden_/wooden_ prefixes, new materials are theoria:<id>_<piece>. */
        public String itemId(String piece) {
            return (vanilla ? "minecraft:" : "theoria:") + prefix + "_" + piece;
        }
    }

    /** kind "ore" or "storage"; hardness may be null only inside gates (vanilla hardness kept). */
    public record Block(String id, String kind, double hardness, double resistance, int xpMin, int xpMax) {}

    public record GateBlock(String id, @Nullable Double hardness) {}

    public record Gate(String ore, int toolIdx, List<GateBlock> blocks) {}

    public record Table(List<Material> materials, List<Block> blocks, List<String> items, List<Gate> gates, List<String> removed) {}

    private static Table table;

    private GearData() {}

    public static synchronized Table table() {
        if (table == null) table = load();
        return table;
    }

    private static Table load() {
        try (InputStream in = GearData.class.getResourceAsStream(RESOURCE)) {
            if (in == null) throw new IllegalStateException("Missing jar resource " + RESOURCE + " (python3 -I generator/gear.py)");
            JsonObject root = JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
            List<Material> materials = new ArrayList<>();
            for (JsonElement e : root.getAsJsonArray("materials")) materials.add(material(e.getAsJsonObject()));
            List<Block> blocks = new ArrayList<>();
            for (JsonElement e : root.getAsJsonArray("blocks")) {
                JsonObject b = e.getAsJsonObject();
                boolean ore = b.get("kind").getAsString().equals("ore");
                blocks.add(new Block(b.get("id").getAsString(), b.get("kind").getAsString(), b.get("hardness").getAsDouble(), b.get("resistance").getAsDouble(),
                        ore ? b.get("xp_min").getAsInt() : 0, ore ? b.get("xp_max").getAsInt() : 0));
            }
            List<String> items = new ArrayList<>();
            for (JsonElement e : root.getAsJsonArray("items")) items.add(e.getAsJsonObject().get("id").getAsString());
            List<Gate> gates = new ArrayList<>();
            for (JsonElement e : root.getAsJsonArray("gates")) {
                JsonObject g = e.getAsJsonObject();
                List<GateBlock> gateBlocks = new ArrayList<>();
                for (JsonElement be : g.getAsJsonArray("blocks")) {
                    JsonObject gb = be.getAsJsonObject();
                    gateBlocks.add(new GateBlock(gb.get("id").getAsString(), gb.get("hardness").isJsonNull() ? null : gb.get("hardness").getAsDouble()));
                }
                gates.add(new Gate(g.get("ore").getAsString(), g.get("tool_idx").getAsInt(), List.copyOf(gateBlocks)));
            }
            List<String> removed = new ArrayList<>();
            for (JsonElement e : root.getAsJsonArray("removed")) removed.add(e.getAsString());
            return new Table(List.copyOf(materials), List.copyOf(blocks), List.copyOf(items), List.copyOf(gates), List.copyOf(removed));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private static Material material(JsonObject m) {
        Armor armor = null;
        if (!m.get("armor").isJsonNull()) {
            JsonObject a = m.getAsJsonObject("armor");
            armor = new Armor(ints(a.getAsJsonObject("points")), a.get("toughness").getAsDouble(), ints(a.getAsJsonObject("durability")),
                    a.get("speed").getAsDouble(), a.get("knockback").getAsDouble());
        }
        Tools tools = null;
        if (!m.get("tools").isJsonNull()) {
            JsonObject t = m.getAsJsonObject("tools");
            Map<String, Kind> kinds = new LinkedHashMap<>();
            for (var entry : t.getAsJsonObject("kinds").entrySet()) {
                JsonObject k = entry.getValue().getAsJsonObject();
                kinds.put(entry.getKey(), new Kind(k.get("damage").getAsDouble(), k.get("speed").getAsDouble()));
            }
            JsonArray spear = t.getAsJsonArray("spear");
            double[] profile = new double[spear.size()];
            for (int i = 0; i < profile.length; i++) profile[i] = spear.get(i).getAsDouble();
            tools = new Tools(t.get("idx").getAsInt(), t.get("durability").getAsInt(), t.get("mining_speed").getAsDouble(), Map.copyOf(kinds), profile);
        }
        return new Material(m.get("id").getAsString(), m.get("vanilla").getAsBoolean(), m.get("idx").getAsInt(), m.get("prefix").getAsString(), m.get("enchantability").getAsInt(),
                m.get("equip_sound").getAsString(), m.get("ingredient").getAsString(), armor, tools);
    }

    private static Map<String, Integer> ints(JsonObject o) {
        Map<String, Integer> out = new LinkedHashMap<>();
        o.entrySet().forEach(e -> out.put(e.getKey(), e.getValue().getAsInt()));
        return Map.copyOf(out);
    }
}
